// Package wordfreq counts case-insensitive ASCII-letter words and ranks them.
package wordfreq

import (
	"cmp"
	"slices"
)

// Entry is a word together with its number of occurrences.
type Entry struct {
	Word  string
	Count int
}

// Count returns the occurrences of each word in data. A word is a maximal run
// of ASCII letters; every other byte is a separator. Words are folded to
// lowercase. Count lowercases data in place.
func Count(data []byte) map[string]int {
	counts := make(map[string]int)
	start := -1
	for i, c := range data {
		switch {
		case 'a' <= c && c <= 'z':
		case 'A' <= c && c <= 'Z':
			data[i] = c | 0x20
		default:
			if start >= 0 {
				counts[string(data[start:i])]++
				start = -1
			}
			continue
		}
		if start < 0 {
			start = i
		}
	}
	if start >= 0 {
		counts[string(data[start:])]++
	}
	return counts
}

// compare orders entries by count descending, then word ascending.
func compare(a, b Entry) int {
	if c := cmp.Compare(b.Count, a.Count); c != 0 {
		return c
	}
	return cmp.Compare(a.Word, b.Word)
}

// Top returns up to n entries of counts, ranked by count descending with
// ties broken by word in ascending byte order.
func Top(counts map[string]int, n int) []Entry {
	if n <= 0 {
		return nil
	}
	top := make([]Entry, 0, min(n, len(counts))+1)
	for word, count := range counts {
		e := Entry{Word: word, Count: count}
		if len(top) == n && compare(e, top[n-1]) >= 0 {
			continue
		}
		i, _ := slices.BinarySearchFunc(top, e, compare)
		top = slices.Insert(top, i, e)
		if len(top) > n {
			top = top[:n]
		}
	}
	return top
}

package wordfreq

import (
	"reflect"
	"testing"
)

func TestCount(t *testing.T) {
	got := Count([]byte("Don't stop_me 4now, now-NOW\xffcaf\xc3\xa9"))
	want := map[string]int{"don": 1, "t": 1, "stop": 1, "me": 1, "now": 3, "caf": 1}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Count = %v, want %v", got, want)
	}
}

func TestTop(t *testing.T) {
	counts := Count([]byte("zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha"))
	got := Top(counts, 10)
	want := []Entry{
		{"alpha", 2}, {"beta", 1}, {"eta", 1}, {"iota", 1}, {"kappa", 1},
		{"lambda", 1}, {"mu", 1}, {"nu", 1}, {"omicron", 1}, {"pi", 1},
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Top = %v, want %v", got, want)
	}
}

func TestTopEmpty(t *testing.T) {
	if got := Top(Count(nil), 10); len(got) != 0 {
		t.Errorf("Top(empty) = %v, want none", got)
	}
}

// Command wordfreq reads standard input and prints the 10 most frequent
// ASCII-letter words, one "<count> <word>" line each.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"

	"wordfreq/internal/wordfreq"
)

const topN = 10

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return fmt.Errorf("reading input: %w", err)
	}

	out := bufio.NewWriter(w)
	for _, e := range wordfreq.Top(wordfreq.Count(data), topN) {
		out.WriteString(strconv.Itoa(e.Count))
		out.WriteByte(' ')
		out.WriteString(e.Word)
		out.WriteByte('\n')
	}
	if err := out.Flush(); err != nil {
		return fmt.Errorf("writing output: %w", err)
	}
	return nil
}
